use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    requires
        true,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
        a@ == old(a@),
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            // bounds
            i <= a.len(),
            // result has exactly the copied prefix
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == a[j],
            // input not modified
            a@ == old(a@),
        decreases a.len() - i,
    {
        // copy element out of `a` (safe because `T: Copy`)
        let x = a[i];
        result.push(x);
        i = i + 1;
    }

    result
}

} // verus!

